using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Diagnostics;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.IO.Compression;using Microsoft.CSharp;using System.CodeDom.Compiler;
class TransactionTests {
 static int passed;static string root;static RSACryptoServiceProvider signer;static JavaScriptSerializer json=new JavaScriptSerializer();
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
 static void Compile(string dest,string version,bool health){string source="using System;using System.IO;using System.Threading;using System.Diagnostics;using System.Reflection;[assembly:AssemblyVersion(\""+version+".0\")] class Fake{static void Main(string[] a){"+(health?"if(a.Length==2){File.WriteAllText(Path.Combine(a[1],\"ready.json\"),\"{\\\"version\\\":\\\""+version+"\\\",\\\"pid\\\":\"+Process.GetCurrentProcess().Id+\"}\");Thread.Sleep(5000);}":"File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,\"started.txt\"),\"old-or-failed-health\");")+"}}";using(var provider=new CSharpCodeProvider()){var args=new CompilerParameters{GenerateExecutable=true,OutputAssembly=dest,CompilerOptions="/target:winexe"};args.ReferencedAssemblies.Add("System.dll");var r=provider.CompileAssemblyFromSource(args,source);if(r.Errors.HasErrors)throw new Exception(r.Errors[0].ToString());}}
 static string Package(string name,bool health,bool traversal){string pending=Path.Combine(root,name);Directory.CreateDirectory(pending);string src=Path.Combine(pending,"new.exe");Compile(src,"2.0.1",health);string zip=Path.Combine(pending,"package.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){z.CreateEntryFromFile(src,"CodexUsageWidget.exe");var helper=z.CreateEntry("WidgetUpdater.exe");using(var w=new StreamWriter(helper.Open()))w.Write("SYNTHETIC HELPER ONLY");if(traversal){using(var w=new StreamWriter(z.CreateEntry("../outside.txt").Open()))w.Write("must not extract");}}
  string payload=json.Serialize(new{version="2.0.1",package_url="https://github.com/"+BuildInfo.Repository+"/releases/download/v2.0.1/TokenWidget-2.0.1-win64.zip",sha256=UpdatePolicy.Hash(zip),size=new FileInfo(zip).Length,notes="SYNTHETIC TRANSACTION FIXTURE"});var bytes=Encoding.UTF8.GetBytes(payload);File.WriteAllText(Path.Combine(pending,"update.json"),json.Serialize(new{payload=Convert.ToBase64String(bytes),signature=Convert.ToBase64String(signer.SignData(bytes,"SHA256"))}));return pending;
 }
 static string Install(string name){string dir=Path.Combine(root,name);Directory.CreateDirectory(dir);Compile(Path.Combine(dir,"CodexUsageWidget.exe"),"2.0.0",false);File.WriteAllText(Path.Combine(dir,"WidgetUpdater.exe"),"OLD HELPER");return dir;}
 static void Main(string[] args){try{if(args.Length==3&&args[0]=="--interrupt"){using(var tx=InstallTransaction.Begin(args[1],new[]{"CodexUsageWidget.exe","WidgetUpdater.exe"})){tx.Replace(args[2],"CodexUsageWidget.exe");Environment.Exit(23);}return;}root=Path.Combine(Path.GetTempPath(),"WidgetTransaction-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);using(signer=new RSACryptoServiceProvider()){signer.PersistKeyInCsp=false;signer.FromXmlString(File.ReadAllText(args[0]));
   string user=Path.Combine(root,"user-data");Directory.CreateDirectory(user);string credentials=Path.Combine(user,"credentials.fixture");File.WriteAllText(credentials,"SYNTHETIC_LOGIN_SENTINEL");
   string good=Install("good-install"),healthy=Package("good-pending",true,false);WidgetUpdater.Apply(healthy,good,true);Check(AssemblyName.GetAssemblyName(Path.Combine(good,"CodexUsageWidget.exe")).Version==new Version(2,0,1,0),"helper installs correct new version");Check(File.ReadAllText(Path.Combine(healthy,"result.txt")).StartsWith("updated"),"helper verifies startup handshake");
   string bad=Install("bad-install"),unhealthy=Package("bad-pending",false,false);bool failed=false;try{WidgetUpdater.Apply(unhealthy,bad,true);}catch(IOException){failed=true;}Check(failed&&AssemblyName.GetAssemblyName(Path.Combine(bad,"CodexUsageWidget.exe")).Version==new Version(2,0,0,0),"failed startup restores old executable");Check(File.ReadAllText(Path.Combine(bad,"WidgetUpdater.exe"))=="OLD HELPER","failed startup restores helper too");
   string blocked=Install("blocked-install"),unsafeZip=Package("unsafe-pending",true,true);failed=false;try{WidgetUpdater.Apply(unsafeZip,blocked,false);}catch(IOException){failed=true;}Check(failed&&!File.Exists(Path.Combine(unsafeZip,"outside.txt")),"path traversal archive rejected before extraction");
   string corrupt=Package("corrupt-pending",true,false);File.AppendAllText(Path.Combine(corrupt,"package.zip"),"CORRUPT");failed=false;try{WidgetUpdater.Apply(corrupt,blocked,false);}catch(IOException){failed=true;}Check(failed&&AssemblyName.GetAssemblyName(Path.Combine(blocked,"CodexUsageWidget.exe")).Version==new Version(2,0,0,0),"corrupt package rejected before replacing installed files");Check(File.ReadAllText(credentials)=="SYNTHETIC_LOGIN_SENTINEL","update and rollback preserve user data");
   string interrupted=Install("interrupted-install"),newExe=Path.Combine(healthy,"new.exe");using(var child=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--interrupt \""+interrupted+"\" \""+newExe+"\""){UseShellExecute=false,CreateNoWindow=true})){if(!child.WaitForExit(10000))throw new Exception("interruption fixture did not exit");Check(child.ExitCode==23&&File.Exists(Path.Combine(interrupted,".update-transaction.json")),"abrupt updater exit leaves durable recovery journal");}Check(AssemblyName.GetAssemblyName(Path.Combine(interrupted,"CodexUsageWidget.exe")).Version==new Version(2,0,1,0),"interruption fixture stopped after first replacement");Check(InstallTransaction.Recover(interrupted)&&AssemblyName.GetAssemblyName(Path.Combine(interrupted,"CodexUsageWidget.exe")).Version==new Version(2,0,0,0)&&File.ReadAllText(Path.Combine(interrupted,"WidgetUpdater.exe"))=="OLD HELPER","next launch recovers interrupted transaction");Check(!InstallTransaction.Recover(interrupted),"recovery is idempotent");
   string partial=Install("partial-install");using(var tx=InstallTransaction.Begin(partial,new[]{"CodexUsageWidget.exe","WidgetUpdater.exe","README.txt"})){bool locked=false;try{using(var guard=new FileStream(Path.Combine(partial,"WidgetUpdater.exe"),FileMode.Open,FileAccess.Read,FileShare.Read)){tx.Replace(newExe,"CodexUsageWidget.exe");tx.Replace(newExe,"README.txt");tx.Replace(newExe,"WidgetUpdater.exe");}}catch(IOException){locked=true;tx.Rollback();}Check(locked&&AssemblyName.GetAssemblyName(Path.Combine(partial,"CodexUsageWidget.exe")).Version==new Version(2,0,0,0)&&!File.Exists(Path.Combine(partial,"README.txt")),"partial installation failure restores existing files and removes added files");}
   Check(File.ReadAllText(credentials)=="SYNTHETIC_LOGIN_SENTINEL","interrupted and partial installations preserve user data");string running=Install("running-launcher-install"),launcher=Path.Combine(running,"TokenWidget.exe"),launcherPending=Path.Combine(root,"launcher-ready");Directory.CreateDirectory(launcherPending);Compile(launcher,"2.0.0",true);string launcherHash=UpdatePolicy.Hash(launcher);Process launcherProcess=InstallTransaction.StartHealthy(launcher,launcherPending,"2.0.0","");try{using(var child=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"--interrupt \""+running+"\" \""+newExe+"\""){UseShellExecute=false,CreateNoWindow=true})){if(!child.WaitForExit(10000))throw new Exception("running-launcher fixture timed out");}InstallTransaction.Recover(running);Check(!launcherProcess.HasExited&&UpdatePolicy.Hash(launcher)==launcherHash&&AssemblyName.GetAssemblyName(Path.Combine(running,"CodexUsageWidget.exe")).Version==new Version(2,0,0,0),"recovery works while stable launcher executable is running");bool rejected=false;try{using(var invalid=InstallTransaction.Begin(running,new[]{"TokenWidget.exe"})){} }catch(IOException){rejected=true;}Check(rejected,"transaction refuses to replace or delete recovery launcher");}finally{InstallTransaction.Stop(launcherProcess);}Console.WriteLine("PASS transaction assertions: "+passed);
  }}catch(Exception e){Console.WriteLine("FAIL "+e.Message);Environment.ExitCode=1;}}
}
